// save as reproduce-render-bug.js
'use strict';

const TableFormatter = require('lighthouse-core/formatters/table.js');
const Handlebars = require('handlebars');
const ReportGenerator = require('lighthouse-core/report/report-generator.js');

// Registers HTML helpers (ifNotEq, etc) for the html formatter
new ReportGenerator();
Handlebars.registerHelper(TableFormatter.getHelpers());

// Pick HTML or pretty text formatter to see the bug in both
const htmlFormatter = TableFormatter.getFormatter('html');
const prettyFormatter = TableFormatter.getFormatter('pretty');

// Test data with backticks, underscores and link-like syntax in the code
const testData = {
  tableHeadings: {
    url: 'URL',
    lineCol: 'Line/Col',
    snippet: 'Snippet',
  },
  results: [{
    url: 'http://example.com',
    line: 42,
    col: 7,
    // Leading backtick should make this entire string raw, but markdown is still applied
    code: '`my_var = fetchData()[0] || defaultValue; // see [docs](https://example.com)`',
    isEval: false,
    pre: 'console.log("hello world");',
    preview: null,
  }]
};

// Render HTML
const htmlTemplate = Handlebars.compile(htmlFormatter);
const htmlOutput = htmlTemplate(testData);
console.log('=== HTML OUTPUT ===');
console.log(htmlOutput);

// Render pretty text
console.log('=== PRETTY OUTPUT ===');
console.log(prettyFormatter(testData));
